// 处理置顶子区
                if (thread.flags.has(ChannelFlags.Pinned)) {
                    try {
                        // 无条件确保子区开启和标注
                        await thread.setArchived(true, '定时重归档');
                        await delay(300);
                        await thread.setArchived(false, '定时重归档');
                        await thread.pin('保持标注');
                    } catch (error) {
                        logTime(`设置置顶子区 ${thread.name} 状态失败: ${handleDiscordError(error)}`, true);
                        // 继续执行，不中断流程
                    }
                }

